package net.fabricmc.fabric.api.event.player;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.EntityHitResult;

/** Fabric API callback (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
@FunctionalInterface
public interface UseEntityCallback {
    Event<UseEntityCallback> EVENT = EventFactory.createArrayBacked(UseEntityCallback.class, ls -> (player, world, hand, entity, hitResult) -> { for (UseEntityCallback l : ls) { InteractionResult r = l.interact(player, world, hand, entity, hitResult); if (r != InteractionResult.PASS) return r; } return InteractionResult.PASS; });

    InteractionResult interact(Player player, Level world, InteractionHand hand, Entity entity, EntityHitResult hitResult);
}
